import{_ as a,C as s,o as i,c as n,j as t,a as r,G as l,a3 as c}from"./chunks/framework.Bvm_liKL.js";const w=JSON.parse('{"title":"User Guide","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/instruction-manual.md","filePath":"en/guide/instruction-manual.md"}'),d={name:"en/guide/instruction-manual.md"};function u(h,e,p,g,m,b){const o=s("ArticleMetadata");return i(),n("div",null,[e[0]||(e[0]=t("h1",{id:"user-guide",tabindex:"-1"},[r("User Guide "),t("a",{class:"header-anchor",href:"#user-guide","aria-label":'Permalink to "User Guide"'},"​")],-1)),l(o),e[1]||(e[1]=c('<h2 id="getting-started" tabindex="-1">Getting Started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting Started&quot;">​</a></h2><p>Hello! Welcome to the ICC CE user guide. This tutorial is designed for beginners who have never used the ICC CE annotation software series, or for users who are still using older versions. This guide details how to use ICC CE correctly to avoid common issues. The content is divided into specific sections for your convenience. Here are some quick tips:</p><ol><li>This software runs on Windows 7 and above, and requires <code>.NET Framework 4.7.2</code>. If you encounter issues installing <code>.NET Framework 4.7.2</code> on Windows 7, please install update <code>Windows6.1-KB3033929-x64</code> (requires Windows 7 SP1).</li></ol><blockquote><p>Windows6.1-KB3033929-x64:<br><a href="https://www.microsoft.com/en-US/download/details.aspx?id=46078" target="_blank" rel="noreferrer">https://www.microsoft.com/en-US/download/details.aspx?id=46078</a></p><p>.NET Framework 4.7.2:<br><a href="https://dotnet.microsoft.com/en-us/download/dotnet-framework/net472" target="_blank" rel="noreferrer">https://dotnet.microsoft.com/en-us/download/dotnet-framework/net472</a></p></blockquote><img src="https://github.com/user-attachments/assets/acdbddd6-7380-439b-a95e-1bdb156d9a4e" alt="Detailed Operation 2" style="width:75%;box-shadow:0 8px 32px rgba(0,0,0,0.25);"><blockquote><p>If the download fails, you can try the offline installer:<br><a href="https://dotnet.microsoft.com/en-us/download/dotnet-framework/thank-you/net472-offline-installer" target="_blank" rel="noreferrer">https://dotnet.microsoft.com/en-us/download/dotnet-framework/thank-you/net472-offline-installer</a></p></blockquote><img src="https://github.com/user-attachments/assets/1d2011be-4e1f-4b6e-af3d-db59aa81b90f" alt="Detailed Operation 1" style="width:75%;box-shadow:0 8px 32px rgba(0,0,0,0.25);"><ol start="2"><li>If you encounter any problems, please submit an issue on the ICC CE GitHub issues page:<br><a href="https://github.com/InkCanvasForClass/community/issues" target="_blank" rel="noreferrer">https://github.com/InkCanvasForClass/community/issues</a></li><li>Since you are already reading this tutorial, we trust that you have the ability to locate resources and find other relevant links. Therefore, they will not be listed individually here.</li></ol><h2 id="settings-section" tabindex="-1">Settings Section: <a class="header-anchor" href="#settings-section" aria-label="Permalink to &quot;Settings Section:&quot;">​</a></h2><p>First, click on the <code>Tools</code> option on the software main page, then click <code>Settings</code>. You will see the settings interface as shown below:</p><img src="https://github.com/user-attachments/assets/abd32bf2-508a-4011-8ca5-4f77b89910a0" alt="Settings Interface" style="width:50%;box-shadow:0 8px 32px rgba(0,0,0,0.25);"><p>:::success In this area, you will find buttons for mode switching and new settings. These two features are currently <strong>under development!</strong><br> :::</p><h3 id="startup-settings" tabindex="-1">Startup Settings <a class="header-anchor" href="#startup-settings" aria-label="Permalink to &quot;Startup Settings&quot;">​</a></h3><p>In the <code>Startup</code> section, you can configure options related to automatic updates, no-focus window mode, run at startup, and launch behavior.</p><blockquote><p>The software provides two update channels: Stable and Beta. The Stable channel offers reliable updates, while the Beta channel provides early access to new features. You can choose based on your needs.</p></blockquote><div class="info custom-block"><p class="custom-block-title">信息</p><p>If you encounter problems during updates, try using the <strong>Fix Version</strong> function. If the current version has issues, you can use the <strong>Rollback to historical version</strong> feature. Before rolling back, you will be asked whether to pause automatic updates.</p></div><div class="info custom-block"><p class="custom-block-title">信息</p><p><strong>No-focus mode</strong> might cause some <strong>always-on-top issues</strong>. It works best when combined with the <strong>Window Topmost</strong> setting.</p></div><div class="info custom-block"><p class="custom-block-title">信息</p><p>The <strong>Borderless</strong> window feature can resolve wallpaper pausing issues under certain conditions.</p></div><h3 id="canvas-and-ink-settings" tabindex="-1">Canvas and Ink Settings <a class="header-anchor" href="#canvas-and-ink-settings" aria-label="Permalink to &quot;Canvas and Ink Settings&quot;">​</a></h3><p>In the <code>Canvas and Ink</code> section, you can configure drawing canvas preferences:</p><blockquote><ol><li>If you use a touch device or stylus and notice the cursor is hidden, please turn on the <code>Show cursor</code> feature;</li><li>If your device has pressure sensitivity issues, try turning on <code>Disable pressure sensitivity</code>;</li><li>The <code>Touch pressure mode</code> is used to simulate pressure sensitivity on devices that lack hardware pressure support;</li><li>We recommend enabling <code>Hide ink after exiting canvas mode</code> to improve the overall experience;</li><li>You can toggle <code>Show center when drawing a circle</code> to view the origin while drawing;</li><li>The new <code>Ink Fadeout</code> option can be quickly toggled in the annotation sub-panel. This is useful when you want drawings to display on the canvas only temporarily.</li></ol></blockquote><div class="info custom-block"><p class="custom-block-title">信息</p><p>Unless you are sure of what you are doing, it is <strong>not recommended</strong> to modify settings in this section other than <code>Eraser Size</code> and the <strong>recommended settings above</strong>, as it might affect application stability.</p></div><div class="warning custom-block"><p class="custom-block-title">警告</p><p><s>The <strong>Insert Image</strong> feature currently has some known issues</s>. Please adjust your settings accordingly.</p></div><h3 id="gesture-settings" tabindex="-1">Gesture Settings <a class="header-anchor" href="#gesture-settings" aria-label="Permalink to &quot;Gesture Settings&quot;">​</a></h3><p>In the <code>Gesture</code> section, you will find options for touch gestures:</p><blockquote><ol><li>The <code>Two-finger drag</code> function is enabled by default. If you do not need it, you can disable it;</li><li>If you encounter an issue where touch inputs cause the annotator to lock into the eraser tool without being able to switch back, please disable palm erase.</li></ol></blockquote><h3 id="ink-correction-settings" tabindex="-1">Ink Correction Settings <a class="header-anchor" href="#ink-correction-settings" aria-label="Permalink to &quot;Ink Correction Settings&quot;">​</a></h3><p>In the <code>Ink Correction</code> section, you will find options for shape recognition and auto-straightening:</p><blockquote><p>If you find that the auto-straightening detection is too strict, you can <strong>adjust the sensitivity higher</strong>.</p></blockquote><div class="info custom-block"><p class="custom-block-title">信息</p><p>If you do not need <strong>Ink Correction</strong>, please turn it off, as it may introduce extra CPU overhead to your computer.</p></div><h3 id="crash-handling-settings" tabindex="-1">Crash Handling Settings <a class="header-anchor" href="#crash-handling-settings" aria-label="Permalink to &quot;Crash Handling Settings&quot;">​</a></h3><p>In the <code>Crash Handling</code> section, you can configure the steps the software takes when it encounters an unexpected crash.</p><div class="tip custom-block"><p class="custom-block-title">提示</p><p>We recommend enabling this feature to minimize the impact of <strong>accidental crashes</strong> during your usage.</p></div><h3 id="powerpoint-integration-settings" tabindex="-1">PowerPoint Integration Settings <a class="header-anchor" href="#powerpoint-integration-settings" aria-label="Permalink to &quot;PowerPoint Integration Settings&quot;">​</a></h3><p>In the <code>PPT Integration</code> (PPT Linkage) section, you will find settings for presentation integration:</p><blockquote><ol><li>Here, you can adjust the position, color, and page number visibility of the page-turning control buttons;</li><li>You can configure gestures used during slideshow presentations;</li><li>You can set up screen capture and ink saving behaviors under slideshow mode;</li><li>You can manage slideshow notification options. These features mostly <strong>take effect after entering slideshow mode</strong>;</li><li>The new <code>PowerPoint integration enhancement</code> pre-loads the PowerPoint process. Although it disables animations when launching PowerPoint, it speeds up startup times and stabilizes the integration;</li><li><strong>WPS Support</strong> affects the <strong>WPP process termination</strong> feature. Both must be enabled simultaneously to achieve stable slideshow integration with WPS Office;</li><li>Enable <strong>Long Press Page Turning</strong> for a more convenient page-switching experience;</li><li>Enable <strong>Skip Slide Animation</strong> to skip slide transition animations instantly when clicking.</li></ol></blockquote><div class="danger custom-block"><p class="custom-block-title">危险</p><p>It is not recommended to use <strong>WPS</strong> and <strong>PowerPoint</strong> simultaneously, as it may cause software instability. If you encounter slideshow connection issues, please refer to the tips below.</p></div><div class="info custom-block"><p class="custom-block-title">信息</p><p>If you cannot link to WPS while only enabling <code>WPS Support</code>, please try enabling both <code>PowerPoint Support</code> and <code>WPP process termination</code> at the same time.</p></div><div class="info custom-block"><p class="custom-block-title">信息</p><p>If you find that PowerPoint COM components are damaged, preventing PowerPoint linkage, please refer to this guide: <a href="https://www.inkeys.top/tutorial/ppt-com.html" target="_blank" rel="noreferrer">【Click here to open】</a>.</p></div><div class="warning custom-block"><p class="custom-block-title">警告</p><p>The current PowerPoint ink management supports opening multiple slideshows, but it may cause unexpected <strong>ink tracking issues</strong>. Additionally, enabling <strong>show page number button</strong> may cause a slight layout shift of the PPT control buttons towards the center.</p></div><h3 id="advanced-settings" tabindex="-1">Advanced Settings <a class="header-anchor" href="#advanced-settings" aria-label="Permalink to &quot;Advanced Settings&quot;">​</a></h3><p>In the <code>Advanced Settings</code> section, you can configure screen touch parameters, logging, exit confirmations, and experimental features. Feel free to modify them as needed.</p><blockquote><ol><li>If screen DPI adjustments occur during use, try enabling the <code>ForceFullScreen</code> option. If the resolution changes, try enabling the <code>ResolutionChangeDetection</code> function;</li><li>You can calibrate the touch multiplier if the circular eraser shows up too large when drawing with fingers or palms. Clicking the corresponding rectangular area with a pen tip will help estimate the touch multiplier;</li><li>If your device uses infrared touch and experiences touch issues, try enabling the <code>Four-side Infrared Mode</code>;</li><li>The <code>AvoidFullScreenHelper</code> option forces the canvas to compress into non-taskbar screen regions.</li></ol></blockquote><div class="info custom-block"><p class="custom-block-title">信息</p><p>We do not recommend modifying logging and backup settings unless requested.</p></div><h3 id="automation-settings" tabindex="-1">Automation Settings <a class="header-anchor" href="#automation-settings" aria-label="Permalink to &quot;Automation Settings&quot;">​</a></h3><p>In the <code>Automation</code> section, you will find settings for automated workflows:</p><blockquote><ol><li>Configure the toolbar to automatically dock or hide when other specific software is running;</li><li>Set the software to automatically terminate certain background processes;</li><li>Manage auto-saving of ink drawings and dock-mode automation;</li><li>The new floating window interception feature consumes more CPU resources, so enable it only if needed;</li><li>The new file association feature helps you quickly open saved ink files by double-clicking them.</li></ol></blockquote><div class="info custom-block"><p class="custom-block-title">信息</p><p>You can configure automation settings freely based on your personal workflow.</p></div><h3 id="random-call-settings" tabindex="-1">Random Call Settings <a class="header-anchor" href="#random-call-settings" aria-label="Permalink to &quot;Random Call Settings&quot;">​</a></h3><p>In the <code>Random Call</code> (Name Picker) section, you will find options for the random name picker feature:</p><blockquote><ol><li>Set the display duration for chosen names and import student/name lists;</li><li>Configure the program to call external third-party name picking software directly;</li><li>Customize name picker background options;</li><li>Manage your timer and countdown configurations.</li></ol></blockquote><hr><h2 id="features-section" tabindex="-1">Features Section <a class="header-anchor" href="#features-section" aria-label="Permalink to &quot;Features Section&quot;">​</a></h2><p>This section guides you through using the primary features of the software.</p><h3 id="initial-state" tabindex="-1">Initial State <a class="header-anchor" href="#initial-state" aria-label="Permalink to &quot;Initial State&quot;">​</a></h3><p>Upon launching the software, you will see the floating toolbar. Below is how to use its main functions:</p><img src="https://github.com/user-attachments/assets/3d2f9a4c-3eba-410a-a7cd-c6c3574240f9" alt="Floating Toolbar" style="width:60%;box-shadow:0 8px 32px rgba(0,0,0,0.25);"><ol><li>If you need to use a whiteboard, click the <code>Whiteboard</code> button.</li><li>Clicking the <code>Annotation</code> button expands the toolbar and enters <code>Canvas Mode</code>, as shown below:</li></ol><p><img src="https://github.com/user-attachments/assets/f47e80a8-05b8-44ab-8c70-6771e97375ea" alt="Canvas Mode" loading="lazy"></p><ol start="3"><li>Click the <code>Tools</code> button to access more utilities.</li></ol><img src="https://github.com/user-attachments/assets/6f68b54d-4729-47f6-8064-b66baf1d1714" alt="More Utilities" style="width:60%;box-shadow:0 8px 32px rgba(0,0,0,0.25);"><h3 id="canvas-mode" tabindex="-1">Canvas Mode <a class="header-anchor" href="#canvas-mode" aria-label="Permalink to &quot;Canvas Mode&quot;">​</a></h3><p><strong>Under Canvas Mode, you can perform writing, erasing, selection, geometric shapes drawing, and more.</strong><br> Here are the basic operations:</p><ol><li>Single-click the active annotation icon to adjust parameters like brush color and thickness.</li></ol><img src="https://github.com/user-attachments/assets/737a9cd5-c63e-4da7-a015-2a7b31137404" alt="Annotation brush settings" style="width:80%;box-shadow:0 8px 32px rgba(0,0,0,0.25);"><ol start="2"><li>The software supports two eraser types: <code>Area Eraser</code> (erases everything inside the eraser boundaries) and <code>Stroke Eraser</code> (deletes entire ink strokes upon touch). Additionally, you can erase using your palm while in drawing mode (similar to Seewo Whiteboard). If you run into palm-erasing issues, please check the <a href="#advanced-settings">Advanced Settings</a> section.</li><li>The lasso select tool allows you to move, resize, or style selected ink strokes. (Note: Cloning ink is only supported under touch input).<br><img src="https://github.com/user-attachments/assets/0acc309d-b181-46bf-b300-2f2a441651c5" alt="Lasso Select Tool" loading="lazy"></li><li>The clear canvas button offers options to clear all annotations, or clear and return immediately to selection mode.</li><li>Click the &quot;Geometry&quot; button to insert various geometric shape presets.<br><img src="https://github.com/user-attachments/assets/1692ff60-e75a-406a-b7e1-c3fc6e873e0e" alt="Geometric Shapes" loading="lazy"></li></ol><div class="info custom-block"><p class="custom-block-title">信息</p><p>The software supports a <strong>quick color palette</strong>. Read <a href="#personalization-settings">here</a> to see how to enable it.</p></div><h3 id="whiteboard-mode" tabindex="-1">Whiteboard Mode <a class="header-anchor" href="#whiteboard-mode" aria-label="Permalink to &quot;Whiteboard Mode&quot;">​</a></h3><p><strong>Under Whiteboard Mode, you can access dedicated drawing and lecturing tools.</strong><br> Here are the basic operations:</p><p><img src="https://github.com/user-attachments/assets/dd1f2b45-ae4e-416f-8539-e063fd1fd86e" alt="Whiteboard Mode" loading="lazy"></p><ol><li>Upon entering Whiteboard mode, you can customize the whiteboard background color.</li></ol><p><img src="https://github.com/user-attachments/assets/323eb5f6-c95b-47c9-af82-d5fa415a0fb4" alt="Background Settings" loading="lazy"></p><ol start="2"><li><p>In Whiteboard mode, you can use touch gestures to pan and zoom the canvas. You can also enable multi-finger drawing to allow multiple users to write simultaneously.<br><img src="https://github.com/user-attachments/assets/f64b8fe5-2561-41aa-af10-592f17f747da" alt="Gestures" loading="lazy"></p></li><li><p>Use the insert image feature to place images on the whiteboard. This supports inserting local files or pasting screenshots.<br><img src="https://github.com/user-attachments/assets/7d930879-fe78-47e8-b6ca-50b04f682880" alt="Insert Image" loading="lazy"></p></li></ol><div class="warning custom-block"><p class="custom-block-title">警告</p><p><s>This feature has some known issues. Please use with caution.</s> (Actually, it has already been fixed!)</p></div><ol start="4"><li>You can add new whiteboard pages, delete pages, or navigate between pages using the whiteboard page manager.<br><img src="https://github.com/user-attachments/assets/4f497449-c23f-4b2d-98d0-05b67a53afe5" alt="Whiteboard Page Manager" loading="lazy"></li></ol><p><strong>Other operations are identical to Canvas Mode and will not be repeated here.</strong></p><h3 id="ppt-slideshow-mode" tabindex="-1">PPT Slideshow Mode <a class="header-anchor" href="#ppt-slideshow-mode" aria-label="Permalink to &quot;PPT Slideshow Mode&quot;">​</a></h3><p><strong>This mode extends Canvas Mode, specifically designed for PowerPoint slide presentation controls.</strong><br><img src="https://github.com/user-attachments/assets/e0d614b9-54b4-4532-8312-c48549ef2f66" alt="PPT Slideshow Mode" loading="lazy"></p><ol><li><p>You will see page-switching control buttons on both sides of the screen. The position and layout of these buttons can be customized. Refer to the <a href="#powerpoint-integration-settings">PPT Settings</a> section.</p></li><li><p>During slideshow presentations, click the exit icon to terminate the slide show.</p></li></ol><h3 id="additional-tools" tabindex="-1">Additional Tools <a class="header-anchor" href="#additional-tools" aria-label="Permalink to &quot;Additional Tools&quot;">​</a></h3><h4 id="dlass-settings" tabindex="-1">Dlass Settings <a class="header-anchor" href="#dlass-settings" aria-label="Permalink to &quot;Dlass Settings&quot;">​</a></h4><img src="https://github.com/user-attachments/assets/4d1e6c93-a881-43ac-a452-6e9f70297e9b" alt="Dlass 1" style="width:80%;box-shadow:0 8px 32px rgba(0,0,0,0.25);"><img src="https://github.com/user-attachments/assets/6cec8dfe-7c24-4547-be75-4d8fb2404aa6" alt="Dlass 2" style="width:80%;box-shadow:0 8px 32px rgba(0,0,0,0.25);"><ol><li>This feature allows you to view uploaded whiteboard notes on the Dlass web platform.</li><li>Supports automatic note uploading.</li></ol><div class="danger custom-block"><p class="custom-block-title">危险</p><p>This service is provided by a third party, not by this software. Please comply with their terms of service!</p></div><h4 id="timer" tabindex="-1">Timer <a class="header-anchor" href="#timer" aria-label="Permalink to &quot;Timer&quot;">​</a></h4><img src="https://github.com/user-attachments/assets/82a09de3-a961-4139-ad52-94f6c1daff4b" alt="Timer" style="width:80%;box-shadow:0 8px 32px rgba(0,0,0,0.25);"><ol><li>If you have used <code>Seewo Whiteboard (EasiNote)</code> or similar software, the timer controls will feel completely familiar.</li><li>The timer configuration window provides common presets. Click the presets to quickly configure the duration.</li><li>Adjusting the target time to zero configures the timer to act as a stopwatch (counting upwards).</li></ol><div class="info custom-block"><p class="custom-block-title">信息</p><p>The time can only be edited before starting. If the input fields are locked, click the <code>Reset</code> button first.</p></div><h4 id="random-call" tabindex="-1">Random Call <a class="header-anchor" href="#random-call" aria-label="Permalink to &quot;Random Call&quot;">​</a></h4><img src="https://github.com/user-attachments/assets/24df9dc7-900d-4497-b086-e1d6a2f38bdf" alt="Random Call 1" style="width:80%;box-shadow:0 8px 32px rgba(0,0,0,0.25);"><img src="https://github.com/user-attachments/assets/14371cf6-b97a-4832-a72f-acf1c49c7f85" alt="Random Call 2" style="width:80%;box-shadow:0 8px 32px rgba(0,0,0,0.25);"><ol><li><strong>Random mode</strong>: Pick names using a randomized algorithm.</li><li><strong>Sequential mode</strong>: Picks names starting from the first selected name, following a fixed sequence.</li><li><strong>Group mode</strong>: Groups names together and draws from each group in sequence.</li><li>The software supports linking to external third-party name picking apps. Click the <code>External Call</code> button to replace the standard pick button with your external app.</li></ol><div class="info custom-block"><p class="custom-block-title">信息</p><p>The <code>External Call</code> feature requires the user to install the third-party name picking software and configure its <strong>Url</strong> and <strong>Plugin</strong> beforehand.</p></div>',94))])}const k=a(d,[["render",u]]);export{w as __pageData,k as default};
